/* USE : NaverMenuLinkMapper.getApiUrl */
SELECT  FN_GET_API_URL(#{storeCd}, #{apiInfo}, #{apiUrl}) AS ${apiUrl}
,       FN_GET_API_URL(#{storeCd}, #{apiInfo}, #{apiKey}) AS ${apiKey}
FROM    DUAL

 /* NaverMenuLinkMapper.getNaverUniqueId */
SELECT  ORDER_UNIQUE_ID AS UNIQUE_ID
FROM    TB_CM_NAVER_LINK
WHERE   HQ_OFFICE_CD = #{hqOfficeCd}
AND     STORE_CD     = #{storeCd}

mapper.update:
/* USE : NaverMenuLinkMapper.resetMenuOptionUseYn */
UPDATE TB_CM_NAVER_ORDER_OPTION
SET    USE_YN = 'N'
WHERE  POS_SHOP_ID = #{posShopId}

mapper.insert:
/* USE : NaverMenuLinkMapper.saveMenuOptionList */
BEGIN

    MERGE INTO TB_CM_NAVER_ORDER_OPTION A
    USING DUAL
    ON (
            A.POS_SHOP_ID = #{item.posShopId}
        AND A.OPTION_ID   = #{item.optionId}
    )
    WHEN MATCHED THEN
    UPDATE
       SET A.NAME = #{item.name}
       ,   A.AGENCY_KEY = #{item.agencyKey}
       ,   A.USE_YN = 'Y'
       ,   A.MOD_DT = #{item.modDt}
       ,   A.MOD_ID = #{item.modId}
    WHEN NOT MATCHED THEN
    INSERT (
        A.POS_SHOP_ID,
        A.OPTION_ID,
        A.NAME,
        A.AGENCY_KEY,
        A.USE_YN,
        A.REG_DT,
        A.REG_ID,
        A.MOD_DT,
        A.MOD_ID
    )
    VALUES (
        #{item.posShopId},
        #{item.optionId},
        #{item.name},
        #{item.agencyKey},
        'Y',
        #{item.regDt},
        #{item.regId},
        #{item.modDt},
        #{item.modId}
    );

END;

mapper.select:
/* USE : NaverMenuLinkMapper.getProdList */
WITH MATCH_PROD_CD AS ( SELECT DISTINCT T.GRP_PROD_CD AS PROD_CD FROM ( -- 모상품 자신 SELECT p.PROD_CD AS GRP_PROD_CD , p.PROD_CD AS ROW_PROD_CD , p.PROD_NM AS ROW_PROD_NM FROM TB_MS_PRODUCT p WHERE p.STORE_CD = #{storeCd} UNION ALL -- 사이드(하위) 상품 SELECT p.PROD_CD AS GRP_PROD_CD , p2.PROD_CD AS ROW_PROD_CD , p2.PROD_NM AS ROW_PROD_NM FROM TB_MS_PRODUCT p INNER JOIN TB_MS_PRODUCT_SDSEL_CLASS sg ON sg.STORE_CD = p.STORE_CD AND sg.SDSEL_GRP_CD = p.SDSEL_GRP_CD AND sg.USE_YN = 'Y' INNER JOIN TB_MS_PRODUCT_SDSEL_PROD sp ON sp.STORE_CD = sg.STORE_CD AND sp.SDSEL_CLASS_CD = sg.SDSEL_CLASS_CD AND sp.USE_YN = 'Y' INNER JOIN TB_MS_PRODUCT p2 ON p2.STORE_CD = sp.STORE_CD AND p2.PROD_CD = sp.PROD_CD WHERE p.STORE_CD = #{storeCd} ) T WHERE 1=1
AND T.ROW_PROD_CD LIKE '%'||#{prodCd}||'%'
AND T.ROW_PROD_NM LIKE '%'||#{prodNm}||'%'
)
SELECT * FROM ( SELECT y.* , MAX(IDX) OVER () AS TOT_CNT FROM ( SELECT DENSE_RANK() OVER (ORDER BY PROD_CD) AS IDX , PROD_CD , PROD_NM , PROD_CLASS_NM , SDSEL_GRP_CD , SDSEL_CLASS_CD , SIDE_PROD_CD , SIDE_PROD_NM , NVL(SIDE_PROD_NM, PROD_NM) AS DISP_PROD_NM , NVL(SIDE_PROD_CD, PROD_CD) AS DISP_PROD_CD , ROW_TYPE , CLASS_SORT , SIDE_SORT FROM ( -- 모상품 헤더 라인 SELECT tmp.PROD_CD , tmp.PROD_NM , ( SELECT SF_GET_PROD_CLASSES('S', tmp.STORE_CD, tmp.PROD_CLASS_CD) FROM DUAL ) AS PROD_CLASS_NM , tmp.SDSEL_GRP_CD , NULL AS SDSEL_CLASS_CD , NULL AS SDSEL_CLASS_NM , NULL AS CLASS_DISP_SEQ , NULL AS SIDE_PROD_CD , NULL AS SIDE_PROD_NM , NULL AS SIDE_PROD_DISP_SEQ , 0 AS ROW_TYPE , 0 AS CLASS_SORT , 0 AS SIDE_SORT FROM TB_MS_PRODUCT tmp INNER JOIN TB_MS_STORE tms ON tms.STORE_CD = tmp.STORE_CD WHERE tmp.STORE_CD = #{storeCd}
AND tmp.REG_DT BETWEEN #{startDate}||'000000' AND #{endDate}||'235959'
AND tmp.PROD_CD IN (SELECT PROD_CD FROM MATCH_PROD_CD)
UNION ALL -- 하위(사이드) 상품 상세 라인 SELECT tmp.PROD_CD , tmp.PROD_NM , ( SELECT SF_GET_PROD_CLASSES('S', tmp2.STORE_CD, tmp2.PROD_CLASS_CD) FROM DUAL ) AS PROD_CLASS_NM , tmp.SDSEL_GRP_CD , tmpsg.SDSEL_CLASS_CD , tmpsg.SDSEL_CLASS_NM , tmpsg.DISP_SEQ AS CLASS_DISP_SEQ , tmpsp.PROD_CD AS SIDE_PROD_CD , tmp2.PROD_NM AS SIDE_PROD_NM , tmpsp.DISP_SEQ AS SIDE_PROD_DISP_SEQ , 1 AS ROW_TYPE , tmpsg.DISP_SEQ AS CLASS_SORT , tmpsp.DISP_SEQ AS SIDE_SORT FROM TB_MS_PRODUCT tmp INNER JOIN TB_MS_STORE tms ON tms.STORE_CD = tmp.STORE_CD INNER JOIN TB_MS_PRODUCT_SDSEL_CLASS tmpsg ON tmpsg.STORE_CD = tmp.STORE_CD AND tmpsg.SDSEL_GRP_CD = tmp.SDSEL_GRP_CD AND tmpsg.USE_YN = 'Y' INNER JOIN TB_MS_PRODUCT_SDSEL_PROD tmpsp ON tmpsp.STORE_CD = tmpsg.STORE_CD AND tmpsp.SDSEL_CLASS_CD = tmpsg.SDSEL_CLASS_CD AND tmpsp.USE_YN = 'Y' LEFT JOIN TB_MS_PRODUCT tmp2 ON tmp2.STORE_CD = tmpsp.STORE_CD AND tmp2.PROD_CD = tmpsp.PROD_CD WHERE tmp.STORE_CD = #{storeCd}
AND tmp.REG_DT BETWEEN #{startDate}||'000000' AND #{endDate}||'235959'
AND tmp.PROD_CD IN (SELECT PROD_CD FROM MATCH_PROD_CD)
) X ) y ) z WHERE IDX BETWEEN #{offset} AND #{limit} ORDER BY PROD_CD, ROW_TYPE, CLASS_SORT, SIDE_SORT

/* USE : NaverMenuLinkMapper.getProdNm */
SELECT  PROD_NM
FROM    TB_MS_PRODUCT
WHERE   STORE_CD = #{storeCd}
AND     PROD_CD  = #{prodCd}
